css:
.p03-top { display: grid; gap: var(--s-2); margin-bottom: var(--s-3); }
.p03-top:empty { display: none; }
.p03-top .explain { justify-content: space-between; }
.p03-empty { display: grid; justify-items: center; text-align: center; gap: var(--s-3); padding: var(--s-5) var(--s-3); }
.p03-empty .prose { margin-inline: auto; }
.p03-btnwrap { position: relative; display: inline-block; }
.p03-btntip { position: absolute; left: 50%; top: calc(100% + var(--s-1)); translate: -50% 0; white-space: nowrap; z-index: 5; }
.p03-tabtip { position: absolute; left: 0; bottom: calc(100% + var(--s-1)); z-index: 30; white-space: nowrap; }
.p03-geartip { position: absolute; right: 0; top: calc(100% + var(--s-1)); z-index: 30; white-space: nowrap; }
.p03-status { display: flex; align-items: center; justify-content: center; gap: var(--s-2); padding: var(--s-5) var(--s-3); }
.p03-err { display: grid; gap: var(--s-3); justify-items: start; max-width: 32rem; margin-inline: auto; padding: var(--s-4) 0; }
.p03-err .banner { width: 100%; }
.p03-tz { flex-wrap: wrap; }
.p03-tz .banner__text { flex: 1 1 18rem; }
.p03-tz__btns { display: flex; flex-wrap: wrap; gap: var(--s-2); }
.app.p03-rel { position: relative; }
.p03-handle { position: absolute; top: 0; bottom: 0; left: min(40rem, clamp(12%, 25%, 50%)); width: var(--s-2); translate: -50% 0; z-index: 10; cursor: col-resize; }
.p03-handle::after { content: ""; position: absolute; top: 0; bottom: 0; left: 50%; width: var(--w2); translate: -50% 0; background: var(--ink); }
.p03-handletip { position: absolute; bottom: 9rem; left: calc(min(40rem, clamp(12%, 25%, 50%)) + var(--s-3)); z-index: 10; }
.p03-e { --frame-w: var(--w2); }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
.p03-end { justify-content: flex-end; }   
.p03-shift .content { margin-top: calc(var(--p03-shift, 0rem) * -1); }
